import{_ as a,c as e,o as n,a6 as r}from"./chunks/framework.B5rgnJXo.js";const h=JSON.parse('{"title":"Coldcard 硬件钱包 RNG 漏洞解剖：Yasmarang 确定性回退如何让 1,367 BTC 无声蒸发","description":"2026 年 7 月末，比特币硬件钱包 Coldcard 曝出历史上规模最大的 RNG 漏洞：固件集成错误导致 ngu.random 调用了 MicroPython 的确定性 Yasmarang 软件生成器，而非 STM32 硬件随机数，攻击者离线枚举即可还原私钥，约 1,367 BTC（价值超 8800 万美元）被盗。本文完整复盘 Block 工程团队的根因分析、受影响设备范围、熵退化估算与防护方案，并探讨 Claude Code 8 分钟复现漏洞的 AI 审计意义。","frontmatter":{"title":"Coldcard 硬件钱包 RNG 漏洞解剖：Yasmarang 确定性回退如何让 1,367 BTC 无声蒸发","date":"2026-08-04T00:00:00.000Z","tags":["security","hardware-wallet","coldcard","rng","bitcoin","firmware","crypto","prompt","supply-chain"],"keywords":["Coldcard RNG 漏洞","Yasmarang","STM32 硬件随机数","比特币硬件钱包","1,367 BTC 被盗","Coinkite","Block 工程团队","MicroPython 随机数回退","熵估算","BIP-39 助记词","Claude Code 漏洞发现"],"category":"security/offensive","description":"2026 年 7 月末，比特币硬件钱包 Coldcard 曝出历史上规模最大的 RNG 漏洞：固件集成错误导致 ngu.random 调用了 MicroPython 的确定性 Yasmarang 软件生成器，而非 STM32 硬件随机数，攻击者离线枚举即可还原私钥，约 1,367 BTC（价值超 8800 万美元）被盗。本文完整复盘 Block 工程团队的根因分析、受影响设备范围、熵退化估算与防护方案，并探讨 Claude Code 8 分钟复现漏洞的 AI 审计意义。","head":[["link",{"rel":"canonical","href":"https://friday-go.icu/security/offensive/coldcard-rng-yasmarang-btc-theft-2026"}],["meta",{"property":"og:image","content":"https://friday-go.icu/images/covers/security-offensive.svg"}],["meta",{"name":"twitter:image","content":"https://friday-go.icu/images/covers/security-offensive.svg"}],["meta",{"name":"keywords","content":"Coldcard RNG 漏洞,Yasmarang,STM32 硬件随机数,比特币硬件钱包,1,367 BTC 被盗,Coinkite,Block 工程团队,MicroPython 随机数回退,熵估算,BIP-39 助记词,Claude Code 漏洞发现, PFinalClub, Golang教程, Go后端开发, Go微服务, PHP, Python, 技术博客"}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"article:published_time","content":"2026-08-04T00:00:00.000Z"}],["meta",{"property":"article:modified_time","content":"2026-08-04T11:45:16.000Z"}],["meta",{"property":"article:author","content":"PFinal南丞"}],["meta",{"property":"article:section","content":"攻防研究"}],["meta",{"property":"article:tag","content":"security"}],["meta",{"property":"article:tag","content":"hardware-wallet"}],["meta",{"property":"article:tag","content":"coldcard"}],["meta",{"property":"article:tag","content":"rng"}],["meta",{"property":"article:tag","content":"bitcoin"}],["meta",{"property":"article:tag","content":"firmware"}],["meta",{"property":"article:tag","content":"crypto"}],["meta",{"property":"article:tag","content":"prompt"}],["meta",{"property":"article:tag","content":"supply-chain"}],["meta",{"name":"citation_title","content":"Coldcard 硬件钱包 RNG 漏洞解剖：Yasmarang 确定性回退如何让 1,367 BTC 无声蒸发"}],["meta",{"name":"citation_author","content":"PFinal南丞"}],["meta",{"name":"citation_date","content":"2026-08-04"}],["meta",{"name":"citation_online_date","content":"2026-08-04"}],["meta",{"property":"og:title","content":"Coldcard 硬件钱包 RNG 漏洞解剖：Yasmarang 确定性回退如何让 1,367 BTC 无声蒸发"}],["meta",{"property":"og:description","content":"2026 年 7 月末，比特币硬件钱包 Coldcard 曝出历史上规模最大的 RNG 漏洞：固件集成错误导致 ngu.random 调用了 MicroPython 的确定性 Yasmarang 软件生成器，而非 STM32 硬件随机数，攻击者离线枚举即可还原私钥，约 1,367 BTC（价值超 8800 万美元）被盗。本文完整复盘 Block 工程团队的根因分析、受影响设备范围、熵退化估算与防护方案，并探讨 Claude Code 8 分钟复现漏洞的 AI 审计意义。"}],["meta",{"property":"og:url","content":"https://friday-go.icu/security/offensive/coldcard-rng-yasmarang-btc-theft-2026"}],["meta",{"name":"twitter:title","content":"Coldcard 硬件钱包 RNG 漏洞解剖：Yasmarang 确定性回退如何让 1,367 BTC 无声蒸发"}],["meta",{"name":"twitter:description","content":"2026 年 7 月末，比特币硬件钱包 Coldcard 曝出历史上规模最大的 RNG 漏洞：固件集成错误导致 ngu.random 调用了 MicroPython 的确定性 Yasmarang 软件生成器，而非 STM32 硬件随机数，攻击者离线枚举即可还原私钥，约 1,367 BTC（价值超 8800 万美元）被盗。本文完整复盘 Block 工程团队的根因分析、受影响设备范围、熵退化估算与防护方案，并探讨 Claude Code 8 分钟复现漏洞的 AI 审计意义。"}],["script",{"type":"application/ld+json"},"{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"TechArticle\\",\\"headline\\":\\"Coldcard 硬件钱包 RNG 漏洞解剖：Yasmarang 确定性回退如何让 1,367 BTC 无声蒸发\\",\\"url\\":\\"https://friday-go.icu/security/offensive/coldcard-rng-yasmarang-btc-theft-2026\\",\\"datePublished\\":\\"2026-08-04T00:00:00.000Z\\",\\"dateModified\\":\\"2026-08-04T11:45:16.000Z\\",\\"wordCount\\":23700,\\"timeRequired\\":\\"PT79M\\",\\"proficiencyLevel\\":\\"Advanced\\",\\"author\\":{\\"@type\\":\\"Person\\",\\"name\\":\\"PFinal南丞\\",\\"url\\":\\"https://friday-go.icu/about\\"},\\"publisher\\":{\\"@type\\":\\"Organization\\",\\"name\\":\\"PFinalClub\\",\\"logo\\":{\\"@type\\":\\"ImageObject\\",\\"url\\":\\"https://friday-go.icu/logo.png\\"}},\\"description\\":\\"2026 年 7 月末，比特币硬件钱包 Coldcard 曝出历史上规模最大的 RNG 漏洞：固件集成错误导致 ngu.random 调用了 MicroPython 的确定性 Yasmarang 软件生成器，而非 STM32 硬件随机数，攻击者离线枚举即可还原私钥，约 1,367 BTC（价值超 8800 万美元）被盗。本文完整复盘 Block 工程团队的根因分析、受影响设备范围、熵退化估算与防护方案，并探讨 Claude Code 8 分钟复现漏洞的 AI 审计意义。\\",\\"inLanguage\\":\\"zh-CN\\",\\"mainEntityOfPage\\":{\\"@type\\":\\"WebPage\\",\\"@id\\":\\"https://friday-go.icu/security/offensive/coldcard-rng-yasmarang-btc-theft-2026\\"},\\"keywords\\":[\\"Coldcard RNG 漏洞\\",\\"Yasmarang\\",\\"STM32 硬件随机数\\",\\"比特币硬件钱包\\",\\"1,367 BTC 被盗\\",\\"Coinkite\\",\\"Block 工程团队\\",\\"MicroPython 随机数回退\\",\\"熵估算\\",\\"BIP-39 助记词\\",\\"Claude Code 漏洞发现\\"],\\"articleSection\\":\\"攻防研究\\"}"],["script",{"type":"application/ld+json"},"{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"BreadcrumbList\\",\\"itemListElement\\":[{\\"@type\\":\\"ListItem\\",\\"position\\":1,\\"name\\":\\"首页\\",\\"item\\":{\\"@id\\":\\"https://friday-go.icu\\",\\"@type\\":\\"WebPage\\"}},{\\"@type\\":\\"ListItem\\",\\"position\\":2,\\"name\\":\\"安全\\",\\"item\\":{\\"@id\\":\\"https://friday-go.icu/security\\",\\"@type\\":\\"WebPage\\"}},{\\"@type\\":\\"ListItem\\",\\"position\\":3,\\"name\\":\\"攻防研究\\",\\"item\\":{\\"@id\\":\\"https://friday-go.icu/security/offensive\\",\\"@type\\":\\"WebPage\\"}},{\\"@type\\":\\"ListItem\\",\\"position\\":4,\\"name\\":\\"Coldcard 硬件钱包 RNG 漏洞解剖：Yasmarang 确定性回退如何让 1,367 BTC 无声蒸发\\",\\"item\\":{\\"@id\\":\\"https://friday-go.icu/security/offensive/coldcard-rng-yasmarang-btc-theft-2026\\",\\"@type\\":\\"Article\\"}}]}"]]},"headers":[],"relativePath":"security/offensive/coldcard-rng-yasmarang-btc-theft-2026.md","filePath":"security/offensive/coldcard-rng-yasmarang-btc-theft-2026.md","lastUpdated":1785843916000}'),o={name:"security/offensive/coldcard-rng-yasmarang-btc-theft-2026.md"};function s(i,t,d,l,c,p){return n(),e("div",{"data-pagefind-body":!0},t[0]||(t[0]=[r(`<h1 id="coldcard-硬件钱包-rng-漏洞解剖-yasmarang-确定性回退如何让-1-367-btc-无声蒸发" tabindex="-1">Coldcard 硬件钱包 RNG 漏洞解剖：Yasmarang 确定性回退如何让 1,367 BTC 无声蒸发 <a class="header-anchor" href="#coldcard-硬件钱包-rng-漏洞解剖-yasmarang-确定性回退如何让-1-367-btc-无声蒸发" aria-label="Permalink to &quot;Coldcard 硬件钱包 RNG 漏洞解剖：Yasmarang 确定性回退如何让 1,367 BTC 无声蒸发&quot;">​</a></h1><blockquote><p>Block 工程团队根因分析 | 2026-07-30 披露 | 硬件钱包史上最大规模 RNG 漏洞</p></blockquote><h2 id="引言" tabindex="-1">引言 <a class="header-anchor" href="#引言" aria-label="Permalink to &quot;引言&quot;">​</a></h2><p>2026 年 7 月 30 日，比特币硬件钱包 <strong>Coldcard</strong> 用户发现大量资金在毫无征兆的情况下被盗。仅仅 41 分钟内，攻击者从 1,196 个地址榨干了约 <strong>1,082 BTC</strong>；随后数日内，Galaxy Research 追踪到第二、第三波攻击，最终确认<strong>被盗总量升至约 1,367 BTC，价值约 8,860 万美元</strong>（不同来源估算区间在 7,000 万~1 亿美元+）。</p><p>这不是传统意义上的&quot;黑客入侵设备&quot;。攻击者在<strong>零破解的情况下离线重建了受害者的私钥</strong>。</p><p>根因是一枚隐藏在固件深处的 RNG（随机数生成器）集成错误：Coldcard 的固件本应调用 <strong>STM32 硬件随机数</strong>，却因一处宏检查错误，静默回退到了 <strong>MicroPython 的确定性软件生成器 Yasmarang</strong>。这个生成器的&quot;随机性&quot;来源于设备 UID 和定时器状态——对一个能猜测 UID 和调用历史的攻击者来说，私钥熵可能从理论上的 128 位暴跌到约 40 位（部分设备）。</p><p>本文基于 <strong>Block 工程与安全团队发布的根因分析</strong>（engineering.block.xyz）、BleepingComputer 与 Coinkite 公告，完整解剖这条受害链，并探讨一个耐人寻味的信号：<strong>Anthropic 的 Claude Code 仅用 8 分钟就独立发现了这个漏洞。</strong></p><h2 id="漏洞速览" tabindex="-1">漏洞速览 <a class="header-anchor" href="#漏洞速览" aria-label="Permalink to &quot;漏洞速览&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项目</th><th>详情</th></tr></thead><tbody><tr><td>受影响设备</td><td>Coldcard Mk2/Mk3（v4.0.0~v4.1.9）、Mk4/Q/Mk5（生产固件）</td></tr><tr><td>根因</td><td><code>ngu.random</code> 使用 MicroPython 确定性 Yasmarang 回退，而非 STM32 硬件 RNG</td></tr><tr><td>熵退化</td><td>Mk2/Mk3 v4：至约 2^40 候选；Mk4/Q/Mk5：至多 2^32（再演时更少）</td></tr><tr><td>被盗规模</td><td>约 1,367 BTC（约 8,860 万美元），4,585+ 地址（截至 8 月 1 日）</td></tr><tr><td>攻击方式</td><td>离线穷举重建私钥 → 生成地址 → 与链上地址比对，命中即转走</td></tr><tr><td>发现者</td><td>Block 工程团队 + Coinkite + 社区研究者（多团队 2026-07-30 联合披露）</td></tr><tr><td>修复固件</td><td>Mk2/Mk3 ≥4.2.0、Mk4/Mk5 ≥5.6.0、Q ≥1.5.0Q（Edge ≥6.6.0X/QX）</td></tr></tbody></table><h2 id="根因-一行宏检查错误导致的-rng-静默降级" tabindex="-1">根因：一行宏检查错误导致的 RNG 静默降级 <a class="header-anchor" href="#根因-一行宏检查错误导致的-rng-静默降级" aria-label="Permalink to &quot;根因：一行宏检查错误导致的 RNG 静默降级&quot;">​</a></h2><p>Block 工程团队将漏洞定位到 Coldcard 固件的 <strong>libngu 库</strong>中。问题出在随机数的集成方式：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>正确路径（应有行为）：</span></span>
<span class="line"><span>  libngu → STM32 硬件 RNG（真正不可预测的随机源）</span></span>
<span class="line"><span></span></span>
<span class="line"><span>实际路径（漏洞行为）：</span></span>
<span class="line"><span>  libngu → MicroPython 的 rng_get() → Yasmarang（确定性软件生成器）</span></span></code></pre></div><p><strong>根因</strong>：生产板卡配置定义 <code>MICROPY_HW_ENABLE_RNG</code> 为 0（因为 Coldcard 提供了独立的硬件 RNG 封装，标记无需重复启用）。但 <strong>libngu 错误地检查了&quot;该宏是否被定义&quot;而非&quot;是否被启用&quot;</strong>。构建因此成功，libngu 绑定到了 MicroPython 的 <code>rng_get()</code>——而宏值为 0 时，该函数使用的是 <strong>Yasmarang 软件生成器</strong>，其种子来自 MCU UID 与定时器寄存器。</p><h3 id="yasmarang-是什么" tabindex="-1">Yasmarang 是什么？ <a class="header-anchor" href="#yasmarang-是什么" aria-label="Permalink to &quot;Yasmarang 是什么？&quot;">​</a></h3><p>Yasmarang 是 MicroPython 内置的一个<strong>确定性伪随机数生成器</strong>，并非加密安全随机源。它的输出由内部状态（p、r、h、s 等变量）通过固定位运算递推产生。一旦初始种子已知，整个输出序列完全确定。</p><p>在 Coldcard 的场景中，初始种子取决于：</p><table tabindex="0"><thead><tr><th>输入</th><th>特征</th><th>安全后果</th></tr></thead><tbody><tr><td>MCU UID</td><td>固定 96 位芯片标识（仅低 32 位使用）</td><td>设备身份，<strong>非新鲜熵</strong></td></tr><tr><td>SysTick</td><td>可预测的周期递减计数器</td><td>最多 80,000（Mk2/Mk3）或 120,000（当前设备）个取值</td></tr><tr><td>RTC-&gt;TR</td><td>时间寄存器</td><td>与启动时间相关，可能静态</td></tr><tr><td>RTC-&gt;SSR</td><td>RTC 亚秒计数器</td><td>与 RTC-&gt;TR 和执行时序相关</td></tr></tbody></table><p>对整个可预测输入的攻击者而言，<strong>流序列可以离线完整重建</strong>。</p><h2 id="受影响设备的细分-熵退化程度" tabindex="-1">受影响设备的细分（熵退化程度） <a class="header-anchor" href="#受影响设备的细分-熵退化程度" aria-label="Permalink to &quot;受影响设备的细分（熵退化程度）&quot;">​</a></h2><p>Block 报告的&quot;回归&quot;（regression）在不同设备代际呈现不同程度：</p><table tabindex="0"><thead><tr><th>设备</th><th>固件（生成密钥时）</th><th>评估</th></tr></thead><tbody><tr><td>Mk1</td><td>全部发布版至 v3.0.6</td><td><strong>不在本次退化范围</strong></td></tr><tr><td>Mk2</td><td>至 v3.2.2</td><td>使用直接 STM32 硬件 RNG</td></tr><tr><td>Mk2</td><td>v4.0.0~v4.1.9</td><td><strong>确认受影响</strong>；无安全再演（reseed）</td></tr><tr><td>Mk3</td><td>至 v3.2.2</td><td>使用直接 STM32 硬件 RNG</td></tr><tr><td>Mk3</td><td>v4.0.0~v4.1.9</td><td><strong>确认受影响</strong>；无安全再演</td></tr><tr><td>Mk4</td><td>生产 v5.0.0 起</td><td><strong>回退仍在</strong>；安全再演仅限 32 位</td></tr><tr><td>Q</td><td>全部生产固件</td><td>同 Mk4 的回退与再演结构</td></tr><tr><td>Mk5</td><td>全部生产固件</td><td>同当前 Mk 固件构造</td></tr></tbody></table><h3 id="熵究竟退化到多少" tabindex="-1">熵究竟退化到多少？ <a class="header-anchor" href="#熵究竟退化到多少" aria-label="Permalink to &quot;熵究竟退化到多少？&quot;">​</a></h3><ul><li><strong>Mk2/Mk3 v4.0.0~v4.1.9</strong>：无任何密码学输入。若攻击者已知 UID 与调用历史，候选空间上界约 <strong>2^40.7</strong>；若 RTC 在冷启动时稳定，仅按 SysTick 计算则窄至约 <strong>2^16.3</strong></li><li><strong>Mk4/Q/Mk5（成功再演）</strong>：安全元件熵被哈希后仅保留 4 字节注入 <code>reseed()</code>，再用它替换一个 32 位 Yasmarang 状态字。对于固定的回退状态与调用历史，可区分的输出流最多 <strong>2^32</strong> 种，平均约 2^31 次候选</li></ul><p>换句话说：<strong>&quot;128 位熵&quot;的保护承诺，在特定设备上实质退化到 40 位甚至 16 位——现代计算力下完全可以并行穷举。</strong></p><h2 id="攻击者如何离线盗走资产" tabindex="-1">攻击者如何离线盗走资产 <a class="header-anchor" href="#攻击者如何离线盗走资产" aria-label="Permalink to &quot;攻击者如何离线盗走资产&quot;">​</a></h2><p>一次典型攻击的完整逻辑链：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1. 攻击者掌握受影响固件的 RNG 实现细节（开源 firmware）</span></span>
<span class="line"><span>2. 对某个 UID / 定时器状态组合，离线枚举可能的种子</span></span>
<span class="line"><span>3. 复现 Yasmarang 序列 → 生成候选私钥 → 导出对应比特币地址</span></span>
<span class="line"><span>4. 遍历链上所有地址，寻找与候选地址的匹配</span></span>
<span class="line"><span>5. 命中即：这枚私钥属于某人 → 签名转账 → 资金归并到攻击者钱包</span></span>
<span class="line"><span>6. 等待受害者补仓 / 新设备上线 → 重复匹配</span></span></code></pre></div><p>这就是为什么攻击可以&quot;无声&quot;完成：受害者无需被&quot;攻破&quot;设备，私钥在他人手中被离线重建。Coinpedia 报道指出，攻击者<strong>提前生成了数百万个候选钱包密钥并等待匹配地址出现在链上</strong>。</p><h3 id="coinkite-的受影响范围清单" tabindex="-1">Coinkite 的受影响范围清单 <a class="header-anchor" href="#coinkite-的受影响范围清单" aria-label="Permalink to &quot;Coinkite 的受影响范围清单&quot;">​</a></h3><p>Coinkite 公告定义的受影响种子包括：</p><ul><li><strong>Mk2 与 Mk3</strong>：固件 4.0.1 至 4.1.9 生成的种子</li><li><strong>Mk4 与 Mk5</strong>：标准版 5.6.0 之前、Edge 版 6.6.0X 之前的设备</li><li><strong>Q</strong>：标准版 1.5.0Q 之前、Edge 版 6.6.0QX 之前的设备</li></ul><h2 id="修复与处置" tabindex="-1">修复与处置 <a class="header-anchor" href="#修复与处置" aria-label="Permalink to &quot;修复与处置&quot;">​</a></h2><p>Coinkite 发布了修复固件，并销毁了所有出厂预装受影响固件的在途设备：</p><table tabindex="0"><thead><tr><th>设备</th><th>修复版本</th></tr></thead><tbody><tr><td>Mk2 / Mk3</td><td>4.2.0 及以上</td></tr><tr><td>Mk4 / Mk5（标准）</td><td>5.6.0 及以上</td></tr><tr><td>Q（标准）</td><td>1.5.0Q 及以上</td></tr><tr><td>Edge 版</td><td>6.6.0X / 6.6.0QX</td></tr></tbody></table><h3 id="受影响用户的迁移步骤" tabindex="-1">受影响用户的迁移步骤 <a class="header-anchor" href="#受影响用户的迁移步骤" aria-label="Permalink to &quot;受影响用户的迁移步骤&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1. 验证现有备份（勿在未备份前升级）</span></span>
<span class="line"><span>2. 安装修复固件</span></span>
<span class="line"><span>3. 生成并稳妥记录新的助记词种子</span></span>
<span class="line"><span>4. 在设备上核对新钱包地址</span></span>
<span class="line"><span>5. 先发一笔小额测试交易确认到账</span></span>
<span class="line"><span>6. 将剩余全部资金迁移到新钱包</span></span></code></pre></div><p><strong>特别提示</strong>：使用额外 BIP-39 口令（passphrase）的用户风险显著较低——因为口令在种子之外提供了额外的一层安全，即使种子熵退化，攻击者还原出基础种子也无法直接动用资产。但这不等同于&quot;安全&quot;，仍建议迁移。</p><h2 id="claude-code-8-分钟复现漏洞-ai-审计的意义" tabindex="-1">Claude Code 8 分钟复现漏洞：AI 审计的意义 <a class="header-anchor" href="#claude-code-8-分钟复现漏洞-ai-审计的意义" aria-label="Permalink to &quot;Claude Code 8 分钟复现漏洞：AI 审计的意义&quot;">​</a></h2><p>本事件最耐人寻味的支线：根据 U.Today、36Crypto 等报道，安全研究员 Medusa 在 X 上称 <strong>Anthropic 的 Claude Code 仅用一次提示、8 分钟思考，就从 Coldcard 源码中独立定位了这枚漏洞</strong>——与攻击者利用的完全相同。</p><blockquote><p>&quot;Claude Code 只用一次提示就找到了 Coldcard 钱包漏洞。它思考了 8 分钟，而我们还没有准备好面对接下来会发生什么。&quot; —— 研究员 Medusa</p></blockquote><p>这个事件承载了双重含义：</p><ol><li><strong>正向</strong>：AI 代码审计能够以极低成本发现真实世界中正在被攻击利用的漏洞。若此类审计在资产上线前被常规执行，部分被盗资金或可避免</li><li><strong>反向</strong>：同一个 AI 能力，被攻击者用于审计目标固件后，同样可以加速漏洞武器化。<strong>AI 审计是双刃剑</strong>——谁先用，谁掌握不对称优势</li></ol><p>对此安全界的反思是：硬件钱包等高风险资产的安全验证，<strong>不能只依赖人类审计员的抽样检查</strong>，而应把 AI 驱动的全量源码审计纳入出厂前的强制环节。</p><h2 id="防御启示总结" tabindex="-1">防御启示总结 <a class="header-anchor" href="#防御启示总结" aria-label="Permalink to &quot;防御启示总结&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1. 硬件钱包用户：</span></span>
<span class="line"><span>   - 立即核查受影响固件版本</span></span>
<span class="line"><span>   - 无论是在受影响设备上生成过的种子，一律迁移</span></span>
<span class="line"><span>   - 若含 BIP-39 口令，风险降低但不豁免迁移</span></span>
<span class="line"><span></span></span>
<span class="line"><span>2. 硬件钱包厂商：</span></span>
<span class="line"><span>   - RNG 采用必须做&quot;启用&quot;检查而非&quot;定义&quot;检查（本漏洞直接教训）</span></span>
<span class="line"><span>   - 出厂前引入 AI 全量源码审计 + 熵健康度自动验证</span></span>
<span class="line"><span>   - 安全元件熵注入必须做全宽注入，不可折叠到 32 位</span></span>
<span class="line"><span></span></span>
<span class="line"><span>3. 整个加密生态：</span></span>
<span class="line"><span>   - RNG 是硬件钱包的信任锚点，任何&quot;确定性回退&quot;都应是红线</span></span>
<span class="line"><span>   - 供应链安全不仅要防后门，更要防&quot;看似正常的功能回归&quot;</span></span></code></pre></div><h2 id="结语" tabindex="-1">结语 <a class="header-anchor" href="#结语" aria-label="Permalink to &quot;结语&quot;">​</a></h2><p>Coldcard 事件暴露了一个残酷的现实：<strong>硬件钱包的安全承诺，可能因为一处宏检查错误而整体坍塌，而其代价以数千万美元计。</strong> 当&quot;128 位熵&quot;的保护在面对可预测的 UID 和定时器时退化到 40 位、16 位甚至 0 位（已确认可复现）时，纸上参数与真实安全之间的距离，被 Communities 用真金白银重新丈量了一次。</p><p>而 Claude Code 8 分钟复现漏洞，则是一个明确的信号：<strong>AI 时代的漏洞发现速度即将超过人类防御响应速度。</strong> 对于手中握着私钥的人来说，尽早迁移、远离确定性随机源，永远不是坏选择。</p><h2 id="参考来源" tabindex="-1">参考来源 <a class="header-anchor" href="#参考来源" aria-label="Permalink to &quot;参考来源&quot;">​</a></h2><ul><li>Block 工程博客：<a href="https://engineering.block.xyz/blog/predictable-rng-fallback-and-32-bit-reseed-in-coldcard-firmware" target="_blank" rel="noreferrer">Predictable RNG Fallback and 32-Bit Reseed in COLDCARD Firmware</a> (2026-07-30)</li><li>BleepingComputer: <a href="https://www.bleepingcomputer.com/news/security/coldcard-wallet-rng-flaw-likely-linked-to-88-million-bitcoin-theft/" target="_blank" rel="noreferrer">COLDCARD wallet RNG flaw likely linked to $88 million Bitcoin theft</a> (2026-08-02)</li><li>U.Today: <a href="https://u.today/claude-identifies-100-million-bitcoin-vulnerability-in-eight-minutes" target="_blank" rel="noreferrer">Claude identifies $100 million bitcoin vulnerability in eight minutes</a> (2026-08-03)</li><li>Coinpedia: <a href="https://coinpedia.org/news/coldcard-wallet-flaw-exposed-hacker-quietly-drains-1082-btc-before-security-warning/" target="_blank" rel="noreferrer">Coldcard Wallet Flaw Exposed? Hacker Quietly Drains 1,082 BTC</a> (2026-08-01)</li></ul>`,50)]))}const u=a(o,[["render",s]]);export{h as __pageData,u as default};
